window.MONSTER_CHUNK_27 = [{"name":"Giant Skunk","cr":3,"xp":800,"alignment":"N","size":"Large","type":"animal","init":3,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":15,"ac_touch":12,"ac_flat_footed":12,"ac_mods":"+3 Dex, +3 natural, -1 size","hp":32,"hd":"5d8+10","hdvalue":5,"fort":5,"ref":7,"will":2,"speed":[{"type":"land","speed":30}],"melee":"bite +5 (1d8+3), 2 claws +5 (1d6+3)","ranged":"spray +5 touch (musk)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"musk"}],"strength":17,"dexterity":16,"constitution":13,"intelligence":2,"wisdom":12,"charisma":9,"baseatk":3,"cmb":7,"cmd":20,"feats":[{"feat":"Ability Focus (musk)"},{"feat":"Power Attack"},{"feat":"Toughness"}],"skills":[{"skill":"Climb","value":7},{"skill":"Perception","value":7},{"skill":"Survival","value":2}],"environments":["temperate forests"],"organizations":["solitary","pair"],"treasure":"none","description_visual":"Snarling and ferocious, this horse-sized skunk emits a frightening growl as it smashes through the undergrowth.","group":"Skunk","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Musk","kind":"Ex","details":"Up to twice per day, a giant skunk can spray a stream of noxious musk at a single target within 30 ft. as a standard action. With a successful ranged touch attack, the creature struck by this spray must make a DC 17 Fortitude save or be nauseated for 1d6 rounds and then sickened for 1d6 minutes by the horrific stench. A successful save reduces the effect to only 1d4 rounds of being sickened. A creature cannot use the scent ability as long as it is affected by this musk. The save DC is Constitution-based, and includes a +2 racial bonus."}],"description":"Much larger than their passive cousins, giant skunks are an aggressive lot. Having a greater bulk to maintain, giant skunks feed on creatures beyond just grubs and insects, often hunting small mammals and reptiles by night in addition to giant versions of insects. While giant skunks are dangerous to nearby settlements, farmers find a positive aspect in their presence, valuing the creatures' taste for giant insects and other more dangerous vermin.","ecology":"","habitat_society":""},{"name":"Giant Wasp","cr":3,"xp":800,"alignment":"N","size":"Large","type":"vermin","init":1,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":14,"ac_touch":10,"ac_flat_footed":13,"ac_mods":"+1 Dex, +4 natural, -1 size","hp":34,"hd":"4d8+16","hdvalue":4,"fort":8,"ref":2,"will":2,"immunities":["mind-affecting effects"],"speed":[{"type":"land","speed":20},{"type":"fly","speed":60,"maneuverability":"good"}],"melee":"sting +6 (1d8+6  plus poison)","space":"10 ft.","reach":"5 ft.","strength":18,"dexterity":12,"constitution":18,"wisdom":13,"charisma":11,"baseatk":3,"cmb":8,"cmd":19,"skills":[{"skill":"Fly","value":3},{"skill":"Perception","value":9}],"environments":["temperate forests"],"organizations":["solitary","pair","group (3-6)","nest (7-19)"],"treasure":"none","description_visual":"This horse-sized wasp is covered in yellow and black vertical stripes-its stinger is the size of a sword and drips with venom.","group":"Wasp","source":"PFRPG Bestiary","special_abilities":[{"type":"Poison","kind":"Ex","details":"Sting-injury; save Fort DC 18; frequency 1/round for 6 rounds; effect 1d2 Dexterity damage; cure 1 save. The save DC is Constitution-based, and includes a +2 racial bonus."}],"description":"Giant wasps nearly always form nests, though not like their much smaller cousins. Each nest functions with one leader (the queen), a few workers, and several soldiers.\n\nThe workers and the queen produce offspring while the soldiers protect the nest and hunt for food. Giant wasp nests are typically found in caves, abandoned houses, or any complex large enough to fit a dozen 10-foottall insects.\n\nGiant wasps attack when hungry or threatened, stinging their prey to death. They take dead or incapacitated opponents back to their lairs as food for their unhatched young-the experience of lying in a wasp nest, paralyzed while its grubs feed, is one of nature's cruelest inventions.\n\nEven when part of a nest, giant wasps tend toward solitary hunting, and it's rare to see more than one at a time.","ecology":"","habitat_society":""},{"name":"Giant Whiptail Centipede","cr":3,"xp":800,"alignment":"N","size":"Huge","type":"vermin","init":0,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":15,"ac_touch":8,"ac_flat_footed":14,"ac_mods":"+7 natural, -2 size","hp":38,"hd":"4d8+20","hdvalue":4,"fort":9,"ref":1,"will":1,"immunities":["mind-affecting effects"],"speed":[{"type":"land","speed":40},{"type":"climb","speed":40}],"melee":"bite +8 (2d6+7 plus poison), tail slap +3 (1d3 nonlethal plus trip)","space":"15 ft.","reach":"15 ft. (20 ft. with tail slap)","strength":25,"dexterity":11,"constitution":21,"wisdom":10,"charisma":2,"baseatk":3,"cmb":12,"cmd":22,"cmd_special":"can't be tripped","skills":[{"skill":"Climb","value":15},{"skill":"Perception","value":4},{"skill":"Stealth","value":0}],"sq":[{"type":"compression"}],"environments":["temperate forests","any underground","warm forests"],"organizations":["solitary","pair","colony (3-6)"],"treasure":"none","description_visual":"An elephantine centipede scurries about, its double tail lashing angrily behind it.","group":"Centipede","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Poison","kind":"Ex","details":"Bite-injury; save Fort DC 17; frequency 1/round for 6 rounds; effect 1d4 Dex; cure 1 save. The save DC is Constitution-based."},{"type":"Tail Slap","kind":"Ex","details":"A giant whiptail centipede's tail slap deals nonlethal damage and gains no bonus from its Strength score on damage dealt."}],"description":"Whiptail centipedes are carrion eaters, though corpses large enough to satiate them are a rarity. Corpses of Huge or larger creatures left to rot often attract whiptail centipedes, who viciously defend their bounty against any who would intrude upon their lairs.","ecology":"","habitat_society":""},{"name":"Giraffe","cr":3,"xp":800,"alignment":"N","size":"Huge","type":"animal","init":2,"senses":[{"type":"low-light vision"}],"ac":16,"ac_touch":10,"ac_flat_footed":14,"ac_mods":"+2 Dex, +6 natural, -2 size","hp":30,"hd":"4d8+12","hdvalue":4,"fort":7,"ref":6,"will":2,"speed":[{"type":"land","speed":50}],"melee":"2 hooves +6 (1d8+5), slam +1 (1d8+2)","space":"15 ft.","reach":"10 ft.","strength":20,"dexterity":15,"constitution":16,"intelligence":2,"wisdom":13,"charisma":7,"baseatk":3,"cmb":10,"cmd":22,"cmd_special":"+4 vs. trip","feats":[{"feat":"Endurance"},{"feat":"Run"}],"skills":[{"skill":"Perception","value":8}],"environments":["warm plains"],"organizations":["solitary","pair","herd (3-10)"],"treasure":"none","description_visual":"This animal, covered in a spotted pattern, has a disproportionately long neck that allows it to tower over other animals.","group":"Herd Animal","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Natural Weapons","kind":"Ex","details":"A giraffe's hoof attacks are primary attacks and its slam attack is a secondary attack."}],"description":"These long-necked animals roam across plains in loose-knit groups, grazing on the upper reaches of acacia trees. Giraffes usually avoid conf lict. However, when its young are threatened or if the giraffe is cornered, it attacks ruthlessly, striking with its powerful hooves. Giraffes rarely use their necks to make slam attacks unless they are fighting among themselves as part of their mating displays. A giraffe is between 16 and 20 ft. tall and weighs 3,500 pounds.","ecology":"","habitat_society":""},{"name":"Greater Witchcrow","cr":3,"xp":800,"alignment":"CE","size":"Small","type":"magical beast","init":3,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"detect magic"},{"type":"low-light vision"}],"ac":15,"ac_touch":15,"ac_flat_footed":11,"ac_mods":"+3 Dex, +1 dodge, +1 size","hp":32,"hd":"5d10+5","hdvalue":5,"fort":5,"ref":7,"will":4,"resists":[{"type":"cold","value":5}],"speed":[{"type":"land","speed":20},{"type":"fly","speed":60,"maneuverability":"good"}],"melee":"2 talons +7 (1d6+1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"hexes","details":"cackle, evil eye [-2, 6 rounds], misfortune [1 round]"}],"spell_like_abilities_caster_level":5,"spell_like_abilities_concentration":6,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect magic"},{"spell":"speak with animals","details":"birds only"}]},{"frequency":"1/day","spells":[{"spell":"ill omen"},{"spell":"mirror image"}]},{"frequency":"3/day","spells":[{"spell":"perceive cues"},{"spell":"vanish"},{"spell":"ventriloquism"}]}],"strength":12,"dexterity":17,"constitution":12,"intelligence":17,"wisdom":16,"charisma":13,"baseatk":5,"cmb":5,"cmb_special":"+2 vs. steal","cmd":19,"cmd_special":"+2 vs. steal","feats":[{"feat":"Combat Expertise"},{"feat":"Dodge"},{"feat":"Flyby Attack","type":"bonus"},{"feat":"Improved Steal"}],"skills":[{"skill":"Bluff","value":5},{"skill":"Fly","value":15},{"skill":"Knowledge (arcana)","value":6},{"skill":"Perception","value":9},{"skill":"Sense Motive","value":6},{"skill":"Sleight of Hand","value":12},{"skill":"Spellcraft","value":6},{"skill":"Stealth","value":15}],"languages":["Abyssal","Aklo","Auran","Common","speak with animals (birds only)"],"sq":[{"type":"apportation"}],"environments":["cold forests","cold plains","temperate forests","temperate plains"],"organizations":["solitary","pair","covey (3-12)","murder (13-30)"],"treasure":"standard","description_visual":"With a raucous cry and a flurry of feathered wings, this jet-black bird takes to the air, an unnatural gleam in its otherworldly eyes.","group":"Witchcrow","source":"AP 67","special_abilities":[{"type":"Apportation","kind":"Su","details":"In large enough groupings (such as a murder), greater witchcrows can perform a cooperative form of magic once per day to open a glowing ring in one place leading to somewhere else on the planet. This always entails a raucous aerial ritual, usually centered on those that wish to make use of this ability. The ritual functions like a teleportation circle (CL 17th), except it requires 1 minute of uninterrupted casting time, the circle doesn't need to be placed on a horizontal surface, and it isn't invisible or hard to detect. After coming into existence, the edges of the circle glow and the effect stays in place for 1 minute. Most witchcrows loathe using this power, but some offer it as a service to those in need of quick travel, demanding a high price for such assistance-usually something in the bargainer's possession that is cherished, extremely valuable, and almost always magical."},{"type":"Hexes","kind":"Su","details":"A greater witchcrow uses hexes as a 5th-level witch. Invariably, these abilities include the cackle, evil eye, and misfortune hexes, and require a successful DC 15 Will save to negate or resist. Witchcrow cackling proves especially unnerving as it sounds like extremely mocking cawing."}],"description":"The dreaded witchcrow, renowned as a harbinger of ill deeds and misfortune, preys on the weak and spies on the unwary. Clever, manipulative, and avaricious in the extreme, these foul birds have no conscience and know no fear. Witchcrows strive to steal not only victims' most cherished possessions, but their hopes and dreams as well. They delight in bringing anguish, sowing doubt even as they feign friendly advice designed to tear down alliances, dupe the gullible, and compromise the virtuous. Despite their deceptive nature, witchcrows can also hold valuable information-or come by such if paid to retrieve it.\n\nWitchcrows value arcane magic above all else, not simply as practitioners-the birds certainly have their own innate talent for witchcraft-but also as collectors. In exchange for their services or valuable information, witchcrows trade for scrolls, potions, and other lesser magic items. Even if such items go unoffered, an intense covetous streak drives witchcrows to pilfer these things if they sense them among a bargainer's possessions. Often, they single out arcane casters as targets for thievery, closing on casters from a distance with their vanish ability and executing flyby attacks to snatch away any baubles they desire. They carry such loot back to their nests to proudly share stories of their daring raids under the preening adulation of their peers. Prolonged spellcasting (casting spells with a casting time greater than 1 round) often attracts witchcrows in the area. They stalk spellcasters in groups, watching for opportunities to steal from them.\n\nEcology\n\nLegends claim the first witchcrows spawned in the Dimension of Dreams-hatched from corrupted eggs nurtured by night hags and released onto other planes to carry out misdeeds. Whether this tale is true or not, these birds often keep company with hags. They sometimes treat with more powerful magical beings as messengers, spies, or informants, traveling in groups for mutual protection. Each covey or murder also follows a migratory pattern, moving between sites of power and areas of unusual magic.\n\nGreater witchcrows not only hoard arcane items, but also are dependent on them for reproduction, siphoning away subtle emanations of magical power to aid their gestation process. The likelihood of an egg hatching into a greater witchcrow increases in direct correlation to the time it spends in close proximity to such items. As a result, female witchcrows are much more active in stealing arcane objects for their nests and aggressively fend off rivals to retain any treasure in their possession. Witchcrows can lay a clutch of up to five eggs every year and remain fertile throughout their entire adult lifespan-approximately 20 to 30 years.\n\nAs a greater witchcrow nears the end of its life, it experiences an unusual phenomenon called the Dreaming, in which it enters a fugue state lasting nearly a week. During this time, it molts and meditates as it comes to terms with the end of its life and attempts to pinpoint its final resting place. Usually, this is a place it particularly enjoyed in the past. Once the bird determines the location and fixates on it, the remaining members of its group invoke their apportation to send it there as its life's reward. Thereafter, the others argue and bicker over any magic items left behind by the elder witchcrow.\n\nHabitat & Society\n\nWitchcrows have an affinity for colder climes, and often masquerade as normal crows living in the fields and forests near the civilized settlements of other creatures. They particularly seek out magical societies where they can gain greater access to arcane items. On Golarion, this makes witchcrows most prevalent in Irrisen, where they've developed a terrible reputation-enough so that the witches of Irrisen (and the people they rule) both fear and revile the birds, marking them for destruction whenever they find them.\n\nIn witchcrow society, greater witchcrows always establish dominance over their lesser kin, rising to lead large congregations of the malicious birds and shepherding them from one habitat to another. Witchcrows always mutually support one another even as they compete for the same resources, following a strict social hierarchy that aggrandizes the most successful thieves among them. Leaders of any given covey collect and dispense the spoils of their activities, assigning arcane treasures to the strongest of their kind during mating season. Those witchcrows that contribute little to the group's success often find themselves with empty nests during these gatherings-or cast out of the flock entirely.","ecology":"Legends claim the first witchcrows spawned in the Dimension of Dreams-hatched from corrupted eggs nurtured by night hags and released onto other planes to carry out misdeeds. Whether this tale is true or not, these birds often keep company with hags. They sometimes treat with more powerful magical beings as messengers, spies, or informants, traveling in groups for mutual protection. Each covey or murder also follows a migratory pattern, moving between sites of power and areas of unusual magic.\n\nGreater witchcrows not only hoard arcane items, but also are dependent on them for reproduction, siphoning away subtle emanations of magical power to aid their gestation process. The likelihood of an egg hatching into a greater witchcrow increases in direct correlation to the time it spends in close proximity to such items. As a result, female witchcrows are much more active in stealing arcane objects for their nests and aggressively fend off rivals to retain any treasure in their possession. Witchcrows can lay a clutch of up to five eggs every year and remain fertile throughout their entire adult lifespan-approximately 20 to 30 years.\n\nAs a greater witchcrow nears the end of its life, it experiences an unusual phenomenon called the Dreaming, in which it enters a fugue state lasting nearly a week. During this time, it molts and meditates as it comes to terms with the end of its life and attempts to pinpoint its final resting place. Usually, this is a place it particularly enjoyed in the past. Once the bird determines the location and fixates on it, the remaining members of its group invoke their apportation to send it there as its life's reward. Thereafter, the others argue and bicker over any magic items left behind by the elder witchcrow.","habitat_society":"Witchcrows have an affinity for colder climes, and often masquerade as normal crows living in the fields and forests near the civilized settlements of other creatures. They particularly seek out magical societies where they can gain greater access to arcane items. On Golarion, this makes witchcrows most prevalent in Irrisen, where they've developed a terrible reputation-enough so that the witches of Irrisen (and the people they rule) both fear and revile the birds, marking them for destruction whenever they find them.\n\nIn witchcrow society, greater witchcrows always establish dominance over their lesser kin, rising to lead large congregations of the malicious birds and shepherding them from one habitat to another. Witchcrows always mutually support one another even as they compete for the same resources, following a strict social hierarchy that aggrandizes the most successful thieves among them. Leaders of any given covey collect and dispense the spoils of their activities, assigning arcane treasures to the strongest of their kind during mating season. Those witchcrows that contribute little to the group's success often find themselves with empty nests during these gatherings-or cast out of the flock entirely."},{"name":"Grick","cr":3,"xp":800,"alignment":"N","size":"Medium","type":"aberration","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"scent"}],"ac":15,"ac_touch":12,"ac_flat_footed":13,"ac_mods":"+2 Dex, +3 natural","hp":27,"hd":"5d8+5","hdvalue":5,"fort":2,"ref":3,"will":6,"dr":"10/magic","speed":[{"type":"land","speed":30},{"type":"climb","speed":20}],"melee":"bite +4 (1d4+1), 4 tentacles -1 (1d4)","space":"5 ft.","reach":"5 ft.","strength":12,"dexterity":14,"constitution":13,"intelligence":3,"wisdom":14,"charisma":5,"baseatk":3,"cmb":4,"cmd":16,"cmd_special":"can't be tripped","feats":[{"feat":"Combat Reflexes"},{"feat":"Skill Focus (Perception)"},{"feat":"Stand Still"}],"skills":[{"skill":"Climb","value":9},{"skill":"Perception","value":12},{"skill":"Stealth","value":6,"special":"+14 in rocky terrain"}],"languages":["Aklo (cannot speak)"],"environments":["any underground"],"organizations":["solitary","cluster (2-5)"],"treasure":"incidental","description_visual":"This pallid, slimy, worm-like creature is the size of a human, its mouth a sickening tangle of tentacles and hooked jaws.","source":"PFRPG Bestiary 2","description":"The worm-like grick is a terror of the caverns and tunnels in which it dwells, lying in wait near heavily traveled underground passages or subterranean cities for the chance to reach forth from the darkness and take its prey. Those laid low by a grick are rarely consumed on the spot. Instead, fresh food is hauled back to the grick's lair in a tight burrow or high on a cavern ledge, where it is consumed in small bites at the grick's leisure. The origins of the grick are not known. Even though the grick has a rudimentary intelligence, it doesn't have any society to speak of, and most are encountered alone. On those occasions when unfortunate travelers meet multiple specimens, groups of gricks don't appear to communicate or work together; each instead attacks individual targets and retreats with its prize as soon as it manages to bring down an opponent. Capable predators, gricks also have a strangely weapon-resistant hide that makes them especially dangerous. Many novice adventurers have fallen to grick attacks merely because they were unable to damage the creature with their nonmagical weapons. Those that are familiar with gricks (especially dwarves, morlocks, and troglodytes) know the best strategy for dealing with them is to fall back and wait for more powerful or magical reinforcements. Gricks rely on their dark coloration and ability to climb walls to keep them out of sight until they're ready to spring an ambush. On occasions when food is scarce in a given region, gricks have been known to travel to the surface and roam the wilderness in search of prey, but these sojourns are almost always out of necessity, and end as soon as the gricks find entrances to new subterranean lairs. They prefer darkness and the comfort of a ceiling overhead, avoiding the open sky and going to great lengths to keep the cover of trees, low clouds, or buildings between them and the empty gulf overhead. Jungle Gricks These surface-adapted varieties of the underground grick are shades of green and lurk in the undergrowth of jungles or climb low-hanging branches to drop on unsuspecting prey. Their racial bonus on Stealth checks applies in forested terrain instead of rocky terrain. Jungle gricks are heartier creatures than their underground-dwelling kin-all jungle gricks possess the advanced creature simple template and gain Toughness as a bonus feat.","ecology":"","habitat_society":""},{"name":"Grothlut","cr":3,"xp":800,"alignment":"CE","size":"Medium","type":"aberration","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["piteous moan (30 ft.)"],"ac":13,"ac_touch":8,"ac_flat_footed":13,"ac_mods":"-2 Dex, +5 natural","hp":42,"hd":"5d8+20","hdvalue":5,"fort":7,"ref":-1,"will":3,"immunities":["acid","mind-affecting effects"],"speed":[{"type":"land","speed":20}],"melee":"2 slams +6 (1d6+3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"digestive spew"},{"type":"disgusting demise"},{"type":"piteous moan"}],"strength":15,"dexterity":6,"constitution":18,"intelligence":1,"wisdom":8,"charisma":5,"baseatk":3,"cmb":5,"cmd":13,"cmd_special":"can't be tripped","feats":[{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Weapon Focus (slam)"}],"skills":[{"skill":"Climb","value":10}],"sq":[{"type":"compression"}],"environments":["any underground"],"organizations":["solitary","rout (2-10)"],"treasure":"none","description_visual":"Pale and glistening with moisture, this sluglike creature stares vacantly as a droning moan escapes its slobbering lips.","group":"Fleshwarp","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Digestive Spew","kind":"Ex","details":"In order to ingest food, a grothlut must first regurgitate its digestive liquids upon its victim. As a standard action, it can spit these liquids on a creature within 5 ft. This spew deals 3d6 acid damage (Reflex DC 15 half). The save DC is Constitution-based."},{"type":"Disgusting Demise","kind":"Ex","details":"When a grothlut reaches 0 or fewer hit points, its digestive organs rupture, freeing alchemical agents that have a violent effect on the rest of the grothlut's internal organs and flesh. This causes an explosion of grothlut viscera within a 30-foot-radius burst of the creature. Though this viscera deals no damage, it's disgusting to behold and its smell can cause living creatures within that radius to become nauseated for 1d4 rounds (Fortitude DC 14 negates). This is a poison effect. The save DC is Constitution-based."},{"type":"Piteous Moan","kind":"Su","details":"Whenever a grothlut sees another creature, it begins to moan as free action. Anyone within 60 ft. who can hear the moan must succeed at a DC 15 Will saving throw or become sickened by the moaning for as long as she can hear it. Every two additional grothluts with the area increase the DC by 1, to a maximum of DC 18. This is a mind-affecting sonic effect. The save DC is Constitution-based."}],"description":"Grothluts are sluglike abominations with vaguely human heads and torsos, and rubbery arms that move awkwardly at their sides. They shuffle mindlessly until other creatures come into view, then piteously moan before slithering forward to attack and feed. Those moans are the last vestige of their formerly human selves crying for release as slivers of the creatures' intellects are forced to continuously relive their transformation. Many fleshcrafters consider the grothlut a failure, as the transformation all but stamps out its human consciousness. Others disagree, arguing that warping the creature's mind makes it more useful, as its stupidity makes it pliable and easy to herd. The drow typically use grothluts only as guardians to slowly patrol the remote edges of their enclaves. Once in position, though, grothluts can be used as crude shock troops, unleashed to soften enemy forces before more valuable warriors wade in and cut down the enemies who have been nauseated by the grothluts' exploded organs and flesh.","ecology":"","habitat_society":""},{"name":"Guardian Doll","cr":3,"xp":800,"alignment":"NE","size":"Tiny","type":"construct","subtypes":["cold"],"init":7,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":16,"ac_touch":15,"ac_flat_footed":13,"ac_mods":"+3 Dex, +1 natural, +2 size","hp":22,"hd":"4d10","hdvalue":4,"fort":1,"ref":4,"will":2,"dr":"5/magic","immunities":["cold","construct traits"],"sr":14,"weaknesses":["susceptible to mind-affecting effects","vulnerable to fire"],"speed":[{"type":"land","speed":30}],"melee":"doll's dagger +10 (1d2-1/19-20 plus 1d6 cold and paralysis)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":4,"spell_like_abilities_concentration":4,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"ray of frost"}]},{"frequency":"1/day","spells":[{"spell":"frost fall"},{"spell":"levitate"}]},{"frequency":"3/day","spells":[{"spell":"alarm"},{"spell":"charm person"},{"spell":"light"},{"spell":"mage hand"},{"spell":"open/close"},{"spell":"prestidigitation"}]}],"strength":8,"dexterity":17,"intelligence":13,"wisdom":12,"charisma":10,"baseatk":4,"cmb":5,"cmd":11,"feats":[{"feat":"Improved Initiative"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Escape Artist","value":5},{"skill":"Linguistics","value":3},{"skill":"Perception","value":5},{"skill":"Stealth","value":15}],"languages":["Common","Hallit","Skald"],"sq":[{"type":"soul focus"}],"environments":["any cold"],"organizations":["solitary","pair","coven (3-8)"],"treasure":"standard","description_visual":"This strange doll is clad in traditional Irriseni peasant clothing, and its eyes glisten with a disturbing curiosity.","source":"Irrisen Land Of Eternal Winter","special_abilities":[{"type":"Doll's Dagger","kind":"Su","details":"The dagger wielded by a guardian doll is treated as a masterwork weapon and delivers 1d6 points of cold damage in addition to its normal damage. Those struck by the dagger must succeed at a DC 12 Fortitude save or be paralyzed by the supernatural cold of the weapon for 1d4 rounds. If the guardian doll is destroyed, its weapon becomes a useless child's toy. The save DC is Charisma-based."},{"type":"Soul Focus","kind":"Su","details":"The soul bound to the doll lives within a focus integrated into the doll or its apparel, typically one of the doll's eyes or a gem embedded into its neck or chest. As long as this soul focus remains intact, it can be used to animate another doll, using the same cost as creating a new construct. Once bound into the soul focus, the soul continues to learn. If it is put into a new doll body, the soul retains its personality and memories from its previous bodies. A soul focus has hardness 8, 12 hit points, and a break DC of 20."},{"type":"Susceptible to Mind-Affecting Effects","kind":"Ex","details":"Like a soulbound doll, a guardian doll is susceptible to mind-affecting effects. However, due to the singular purpose with which it is imbued, its saves against such effects are made with a +1 racial bonus."}],"description":"Guardian dolls are constructs created by the White Witches to serve as spies and sentries at places that require ever-vigilant wardens-especially the wintry nation's borders. Similar to soulbound dolls, these strange automatons are infused with fragments of the souls of living beings slain during the dolls' creation. The doll is sentient, and though a small part of the soul's original personality remains, the witchery employed largely strips it of its individuality. Many guardian dolls sit inside another form of construct-a sentinel hut- and stand vigil at one of Irrisen's borders and monitoring those who would enter. Others are sent on scouting missions or to spy on targets, usually posing as inanimate dolls to hide their true nature.\n\nConstruction\n\nA guardian doll's body is made of porcelain or wood, plus one exquisite item worth at least 600 gp to serve as the soul focus. Creation requires a soul fragment from a dead creature that dies at some point during the creation of the doll. An unwilling soul can resist with a successful DC 20 Will save. Stripping a soul fragment from a dead creature doesn't prevent the rest of the soul from continuing to the afterlife, nor does it prevent the body from being resurrected or raised from the dead.\n\nGuardian Doll\n\nCL 8th; Price 6,600 gp\n\nCONSTRUCTION\n\nRequirements Craft Construct, false life, lesser geas, magic jar, minor creation, sleet storm, soul of a living creature who dies or is slain during the creation process, creator must be caster level 8th; Skill Craft (sculpture) DC 16; Cost 3,600 gp","ecology":"","habitat_society":""},{"name":"Guardian Scroll","cr":3,"xp":800,"alignment":"N","size":"Tiny","type":"construct","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":15,"ac_touch":15,"ac_flat_footed":12,"ac_mods":"+2 Dex, +1 dodge, +2 size","hp":27,"hd":"5d10","hdvalue":5,"fort":1,"ref":5,"will":1,"dr":"5/magic","immunities":["bludgeoning","crushing","and falling damage","construct traits"],"weaknesses":["susceptible to mind-affecting effects","vulnerable to fire"],"speed":[{"type":"land","speed":10},{"type":"fly","speed":40,"maneuverability":"perfect"}],"melee":"slice +9 (1d4+3 plus bleed and grab)","space":"2-1/2 ft.","reach":"0 ft.","special_attacks":[{"type":"bleed","details":"1d2"},{"type":"constrict","details":"1d4+3"},{"type":"grab","details":"Medium"},{"type":"slice"},{"type":"strangle"}],"strength":14,"dexterity":15,"intelligence":4,"wisdom":10,"charisma":12,"baseatk":5,"cmb":5,"cmb_special":"+4 vs. grapple","cmd":18,"feats":[{"feat":"Dodge"},{"feat":"Flyby Attack"},{"feat":"Lightning Reflexes"}],"skills":[{"skill":"Acrobatics","value":4},{"skill":"Fly","value":20}],"languages":["Common (can't speak)"],"environments":["any"],"organizations":["solitary","pair","collection (3-6)"],"treasure":"none","description_visual":"This innocuous-looking scroll abruptly rises in the air, unraveling as it flies. It flits about with serpentine grace, baring its razor-sharp edges.","source":"AP 79","special_abilities":[{"type":"Slice","kind":"Ex","details":"A guardian scroll's slice attack is a primary attack that deals slashing damage."},{"type":"Strangle","kind":"Ex","details":"When a guardian scroll grapples a creature, it entirely covers its opponent's head with an airtight grip. A creature grappled by the scroll cannot see, speak, or cast spells with verbal components, and it must hold its breath (see Suffocation). Creatures that don't speak or breathe through their heads aren't affected in those manners, nor are those who can see through other means blinded. Any attacks targeting a guardian scroll while it's grappling deal half damage to the scroll and the other half to the grappled creature."},{"type":"Susceptible to Mind-Affecting Effects","kind":"Ex","details":"As an intelligent construct, a guardian scroll is subject to mind-affecting effects."}],"description":"Magical practitioners, both arcane and divine, often use artificial creatures to protect their lairs, libraries, temples, and sacred texts. Sometimes the best of these protectors are ones a thief never suspects-until it's too late. Guardian scrolls are deceptive constructs created from enchanted paper or papyrus. When an intruder enters a proscribed area or touches a prohibited object without first speaking a password or otherwise signaling that it has permission to enter, the guardian scroll rises to attack.\n\nAt rest, guardian scrolls appear identical to any number of different types of magical or nonmagical scrolls. Sometimes their ends terminate in wooden or light metal rods. These weighted ends don't hinder or alter the guardian scrolls' ability to move and attack. The texture of such a scroll is quite different from that of any paper, parchment, or papyrus-though from visual inspection alone it's indistinguishable from those materials. Instead, a guardian scroll's papery body is surprising strong and tensile. Even with casual handling, an observer can tell the material is tear-resistant, though it has a fine edge.\n\nWhen a guardian scroll becomes active, it rises in the air and unfurls to a length of almost 4 ft. It wafts through the air with casual ease as it approaches its target. When it attacks, it stiffens its edges, making them almost as sharp as razors. It races past its target and draws its entire length across any exposed flesh, leaving a long, deep, and often painful slash that bleeds badly afterward. This isn't the scroll's only means of attack, however. It can also wrap itself around a Medium or smaller creature in the blink of an eye, constricting it. While the strength of its constriction isn't as terrible as that of a giant snake, the guardian scroll is intelligent enough to strategically wrap itself around the face of its target to blind and asphyxiate. While some barroom adventurers laugh at the absurdity of \"aggressive paper,\" anyone who has faced a guardian scroll knows its tenacity is surpassed only by its viciousness.\n\nEcology\n\nGuardian scrolls are artificial creatures, more akin to intelligent magic items than anything spawned in nature. Many do have some connection to the natural world, in that the material used in the creation of their paper is sometimes harvested from treants, quickwoods, or other intelligent tree creatures. In Osirion, guardian scrolls are often created from patches of stranglereeds that grow along the riverbank. Some researchers argue this explains the almost murderous nature that some guardian scrolls manifest. It is possible to create a guardian scroll without killing an intelligent plant creature, but it's a lengthier process that requires much more material, and doesn't appear to change the construct's disposition.\n\nUnlike most constructs, guardian scrolls have a limited intelligence. They lack the bludgeoning strength of other automata, and the variety and sophistication of their possible attacks require more than a simple brute force approach. This same spark of awareness also makes them subject to attacks on their minds.\n\nSometimes a guardian scroll's creator uses the scroll to record the very information the construct is intended to protect-often a treasure map. The idea is that the scroll fights relentlessly rather than allowing an unauthorized party to study it, such that a would-be thief must destroy it to stop its attacks. This is risky, however. The scroll could be grappled, pinned, and held down by two or more creatures so it could be examined. Worse, since it fights to the death, the information it protects could be lost entirely.\n\nGuardian scrolls forced into scroll tubes go dormant unless they succeed at a DC 15 Will save. A scroll that is still active can usually pop the canister open and escape unless the case has a locking mechanism or other special precautions are taken. If its tube is disturbed, a dormant guardian scroll must attempt a Will save to shake off this forced quiescence; if successful, it abruptly returns to life.\n\nHabitat & Society\n\nOne might expect that guardian scrolls would be found only in the lairs of wizards and in great libraries, but the truth is that while they are commonly placed wherever someone has a secret to keep, they can be found in any number of surprising locations. The scrolls make splendid treasure maps for pirate lords, and as such they are found on ships and islands throughout the Inner Sea. They've even been sent anonymously as sealed missives via courier with instructions to murder the recipient.\n\nConstruction\n\nA guardian scroll's body is usually made of paper crafted from the body of a living, intelligent tree or plant creature; the complex process of extraction usually destroys the creature in the process. For this reason, the creation of a guardian scroll is often, but not strictly, an evil act. A Large- or Medium-sized creature can provide more than enough paper to create dozens of guardian scrolls. The paper produced doesn't need to be used within a specific time frame, and so may be sold and purchased without the creator destroying an intelligent creature herself. The paper can also be produced alchemically from normal sources of pulp at greater expense with a successful DC 25 Craft (alchemy) check. The additional cost and price for this alternative process are listed within parentheses in the stat block below. Additionally, the creator must inscribe a series of magical words at the very bottom of the scroll. This doesn't prohibit the scroll from use for spells or other writings, but does require meticulous calligraphy or penmanship.\n\nGUARDIAN SCROLL\n\nCL 8th; Price 5,000 gp (7,500 gp)\n\nConstruction\n\nRequirements Craft Construct, bull's strength, false life, fly, lesser geas, magic weapon, make whole; paper made from an intelligent plant creature that dies or is slain during the paper-making process, or a more costly alchemically treated paper; creator must have 5 ranks in Linguistics; Cost 2,500 gp (3,750 gp)\n\nMagic Guardian Scrolls It's possible to include additional magical writings in the process of a guardian scroll's creation. This process is more expensive, adding 10,000 gp to the construction cost, but grants the guardian scroll spell-like abilities determined by its creator. To make a magic guardian scroll, apply the following changes.\n\nChallenge Rating: +1\n\nAbilities: +2 Int, +2 Cha. The guardian scroll gains no additional skill ranks.\n\nSpell-like Abilities: CL 4th, concentration +6, two 1st-level spells and one 2nd-level spell three times per day, one 3rd-level spell once per day. The creator designates the spells from those the creator can cast.","ecology":"Guardian scrolls are artificial creatures, more akin to intelligent magic items than anything spawned in nature. Many do have some connection to the natural world, in that the material used in the creation of their paper is sometimes harvested from treants, quickwoods, or other intelligent tree creatures. In Osirion, guardian scrolls are often created from patches of stranglereeds that grow along the riverbank. Some researchers argue this explains the almost murderous nature that some guardian scrolls manifest. It is possible to create a guardian scroll without killing an intelligent plant creature, but it's a lengthier process that requires much more material, and doesn't appear to change the construct's disposition.\n\nUnlike most constructs, guardian scrolls have a limited intelligence. They lack the bludgeoning strength of other automata, and the variety and sophistication of their possible attacks require more than a simple brute force approach. This same spark of awareness also makes them subject to attacks on their minds.\n\nSometimes a guardian scroll's creator uses the scroll to record the very information the construct is intended to protect-often a treasure map. The idea is that the scroll fights relentlessly rather than allowing an unauthorized party to study it, such that a would-be thief must destroy it to stop its attacks. This is risky, however. The scroll could be grappled, pinned, and held down by two or more creatures so it could be examined. Worse, since it fights to the death, the information it protects could be lost entirely.\n\nGuardian scrolls forced into scroll tubes go dormant unless they succeed at a DC 15 Will save. A scroll that is still active can usually pop the canister open and escape unless the case has a locking mechanism or other special precautions are taken. If its tube is disturbed, a dormant guardian scroll must attempt a Will save to shake off this forced quiescence; if successful, it abruptly returns to life.","habitat_society":"One might expect that guardian scrolls would be found only in the lairs of wizards and in great libraries, but the truth is that while they are commonly placed wherever someone has a secret to keep, they can be found in any number of surprising locations. The scrolls make splendid treasure maps for pirate lords, and as such they are found on ships and islands throughout the Inner Sea. They've even been sent anonymously as sealed missives via courier with instructions to murder the recipient.\n\nConstruction\n\nA guardian scroll's body is usually made of paper crafted from the body of a living, intelligent tree or plant creature; the complex process of extraction usually destroys the creature in the process. For this reason, the creation of a guardian scroll is often, but not strictly, an evil act. A Large- or Medium-sized creature can provide more than enough paper to create dozens of guardian scrolls. The paper produced doesn't need to be used within a specific time frame, and so may be sold and purchased without the creator destroying an intelligent creature herself. The paper can also be produced alchemically from normal sources of pulp at greater expense with a successful DC 25 Craft (alchemy) check. The additional cost and price for this alternative process are listed within parentheses in the stat block below. Additionally, the creator must inscribe a series of magical words at the very bottom of the scroll. This doesn't prohibit the scroll from use for spells or other writings, but does require meticulous calligraphy or penmanship.\n\nGUARDIAN SCROLL\n\nCL 8th; Price 5,000 gp (7,500 gp)\n\nConstruction\n\nRequirements Craft Construct, bull's strength, false life, fly, lesser geas, magic weapon, make whole; paper made from an intelligent plant creature that dies or is slain during the paper-making process, or a more costly alchemically treated paper; creator must have 5 ranks in Linguistics; Cost 2,500 gp (3,750 gp)\n\nMagic Guardian Scrolls It's possible to include additional magical writings in the process of a guardian scroll's creation. This process is more expensive, adding 10,000 gp to the construction cost, but grants the guardian scroll spell-like abilities determined by its creator. To make a magic guardian scroll, apply the following changes.\n\nChallenge Rating: +1\n\nAbilities: +2 Int, +2 Cha. The guardian scroll gains no additional skill ranks.\n\nSpell-like Abilities: CL 4th, concentration +6, two 1st-level spells and one 2nd-level spell three times per day, one 3rd-level spell once per day. The creator designates the spells from those the creator can cast."},{"name":"Hag Eye Ooze","cr":3,"xp":800,"alignment":"N","size":"Small","type":"ooze","init":-5,"senses":[{"type":"blindsight","modifier":"60 ft."}],"ac":6,"ac_touch":6,"ac_flat_footed":6,"ac_mods":"-5 Dex, +1 size","hp":34,"hd":"4d8+16","hdvalue":4,"fort":5,"ref":-4,"will":1,"immunities":["acid","cold","ooze traits"],"resists":[{"type":"fire","value":5}],"speed":[{"type":"land","speed":20},{"type":"climb","speed":20}],"melee":"slam +6 (1d4+3 plus paralysis)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"paralysis","details":"1d4 rounds, DC 16"},{"type":"spell channel"}],"strength":12,"dexterity":1,"constitution":18,"wisdom":1,"charisma":1,"baseatk":3,"cmb":6,"cmd":11,"cmd_special":"can't be tripped","skills":[{"skill":"Climb","value":10}],"sq":[{"type":"suction"},{"type":"transparent"}],"environments":["temperate marshes","temperate underground"],"organizations":["solitary"],"treasure":"none","description_visual":"A single eye stares unblinking from an amorphous blob. A transparent pseudopod extends from the mass, ready to strike.","group":"Hag Eye Ooze","source":"AP 72","special_abilities":[{"type":"Spell Channel","kind":"Su","details":"A hag creator of a hag eye ooze can see through the embedded hag eye as if she were looking from the ooze directly. This ability requires that the hag creator and the hag eye ooze be on the same plane in order to function. If the hag that created the hag eye ooze is part of a coven, the following spells have a 5% chance per caster level of operating through a hag eye ooze: detect chaos, detect evil, detect good, detect law, detect magic, message, read magic, and tongues. A non-hag that controls a hag eye ooze can't cast spells through the ooze, nor can it see through the creature, but it can target the hag eye ooze with a clairaudience/clairvoyance spell and view through it in that manner."},{"type":"Suction","kind":"Ex","details":"A hag eye ooze can create a powerful suction against any surface it climbs, allowing it to cling to inverted surfaces with ease. It can establish or release suction as a swift action, and as long as it is using suction, it moves at half speed. Because of the suction, a hag eye ooze gains a +10 bonus to its CMD to resist bull rush attacks, awesome blow attacks, and other attacks and effects that attempt to physically move it from its location."},{"type":"Transparent","kind":"Ex","details":"A hag eye ooze is difficult to discern from its surroundings in most environments. A successful DC 15 Perception check is required to notice a hag eye ooze. Any creature that fails to notice it and walks into it automatically suffers damage as if struck by the hag eye ooze's slam attack."}],"description":"Some hags create hag eye oozes to serve as scouts and spies, favoring them over humanoid servants due to the ease of control. With their ability to blend in with their surroundings and climb nearly any surface, these creatures patrol the hag's lair and surrounding territory. Hag eye oozes seem to be imbued with a sliver of the cautious side of their creator's personality, watching intruders from a distance and avoiding combat unless directed to attack. Once given a command, these creatures pursue their goal mindlessly until a countermand is given.\n\nHag eye oozes have gelatinous, transparent bodies that can sometimes grow larger than 5 cubic ft., though most are smaller, taking up roughly half that space. To date, no specimens have been found weighing more than 500 pounds.\n\nCreating a Hag Eye Ooze\n\nThe process of creating a hag eye ooze is a strange blend of cooking in a cauldron and the magic rituals involved in sparking simulated life into a construct. Creating a hag eye ooze requires 2 weeks. This time is reduced if the brewer is working cooperatively. For each additional member of a coven involved in the process, the creation time is lessened by 2 days, to a minimum creation period of 3 days. During this period, various nutrients and ingredients must be added to the cauldron in which the ooze is brewed. As the ingredients are added the hag must consult strange texts and foul recipes to assure proper creation. If she misses a step or poorly measures a reagent, the necessary arcane energies to create the hag eye ooze don't properly bind to the creature's nascent form. If successful, she then begins a 24-hour ritual, during which the cauldron holding the brewing ooze is bombarded with spells. This ritual and spellcasting culminates in the addition of a hag eye- preferably from the hag creator. If the ritual is successful, the hag eye ooze animates fully formed and able to serve as a minion. The hag eye ooze is under the control of the creator, but in cases where a coven takes part in creating the ooze, control goes to the hag that supplied the hag eye.","ecology":"","habitat_society":""},{"name":"Hammerhead Shark","cr":3,"xp":800,"alignment":"N","size":"Large","type":"animal","subtypes":["aquatic"],"init":7,"senses":[{"type":"blindsense","modifier":"30 ft."},{"type":"keen scent"}],"ac":18,"ac_touch":12,"ac_flat_footed":15,"ac_mods":"+3 Dex, +6 natural, -1 size","hp":30,"hd":"4d8+12","hdvalue":4,"fort":9,"ref":7,"will":20,"speed":[{"type":"swim","speed":60}],"melee":"bite +7 (1d8+7)","space":"10 ft.","reach":"5 ft.","strength":21,"dexterity":16,"constitution":17,"intelligence":1,"wisdom":16,"charisma":6,"baseatk":3,"cmb":25,"cmb_special":"+4 vs. grapple","cmd":42,"cmd_special":"can't be tripped","feats":[{"feat":"Great Fortitude"},{"feat":"Improved Initiative"}],"skills":[{"skill":"Perception","value":10},{"skill":"Swim","value":13}],"environments":["any oceans"],"organizations":["solitary","pair","school (3-6)","pack (7-13)"],"treasure":"none","description_visual":"Beneath this sleek gray shark's unusually shaped head, a disproportionately small mouth flashes with razor-sharp teeth.","group":"Shark","source":"AP 57","description":"Hammerheads' heads give them a wider field of vision and allow them to pin prey to the seaf loor before devouring it.","ecology":"","habitat_society":""},{"name":"Hell Hound","cr":3,"xp":800,"alignment":"LE","size":"Medium","type":"outsider","subtypes":["evil","extraplanar","fire","lawful"],"init":5,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"scent"}],"ac":16,"ac_touch":11,"ac_flat_footed":15,"ac_mods":"+1 Dex, +5 natural","hp":30,"hd":"4d10+8","hdvalue":4,"fort":6,"ref":5,"will":1,"immunities":["fire"],"weaknesses":["vulnerability to cold"],"speed":[{"type":"land","speed":40}],"melee":"bite +5 (1d8+1 plus 1d6 fire)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"breath weapon","details":"10-ft. cone, once every 2d4 rounds, 2d6 fire damage, Reflex DC 14 for half"}],"strength":13,"dexterity":13,"constitution":15,"intelligence":6,"wisdom":10,"charisma":6,"baseatk":4,"cmb":5,"cmd":16,"cmd_special":"+4 vs. trip","feats":[{"feat":"Improved Initiative"},{"feat":"Run"}],"skills":[{"skill":"Acrobatics","value":8},{"skill":"Perception","value":7},{"skill":"Stealth","value":13},{"skill":"Survival","value":7}],"languages":["Infernal (cannot speak)"],"environments":["any (Hell)"],"organizations":["solitary","pair","pack (3-12)"],"treasure":"incidental","description_visual":"This creature resembles a thin, lanky wolf with reddish-brown fur, white claws, and burning, fiery red eyes.","source":"PFRPG Bestiary","description":"A typical hell hound stands 4-5 ft. tall at the shoulder and weighs 120 pounds. Efficient hunters, a favorite pack tactic is to surround prey quietly, then attack with one or two hounds, driving prey toward the rest of the pack with their fiery breath.\n\nIf the prey doesn't run, the pack closes in. Hell hounds track fleeing creatures relentlessly.\n\nHell hounds are particularly favored by fire giants, as the creatures are immune to fire and share the fire giant's sense of cruelty when it comes to handling intruders. Only when a fire giant goes too far toward treating a relatively intelligent hell hound like a pet do such alliances begin to falter.","ecology":"","habitat_society":""},{"name":"Howler","cr":3,"xp":800,"alignment":"CE","size":"Large","type":"outsider","subtypes":["chaotic","evil","extraplanar"],"init":6,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":15,"ac_touch":11,"ac_flat_footed":13,"ac_mods":"+2 Dex, +4 natural, -1 size","hp":37,"hd":"5d10+10","hdvalue":5,"fort":6,"ref":6,"will":3,"defensive_abilities":["quill defense"],"speed":[{"type":"land","speed":60}],"melee":"bite +8 (1d8+4), quills +3 (1d4+2 plus pain)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"howl"}],"strength":18,"dexterity":15,"constitution":15,"intelligence":6,"wisdom":14,"charisma":11,"baseatk":5,"cmb":10,"cmd":22,"feats":[{"feat":"Combat Reflexes"},{"feat":"Improved Initiative"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Acrobatics","value":10,"special":"+22 jump"},{"skill":"Climb","value":12},{"skill":"Perception","value":13},{"skill":"Stealth","value":6}],"languages":["Abyssal (cannot speak)"],"environments":["any land (Abyss)"],"organizations":["solitary","pack (2-4)"],"treasure":"incidental","description_visual":"This vile predator has a hide as thick and tough as leather. Wicked ebony quills run from its head, tail, and back.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Howl","kind":"Su","details":"A howler's constant howling is a grating, exhausting baying that can drive listeners insane. All beings other than outsiders within 120 ft. of a howling howler must succeed on a DC 12 Will save or become cursed by the creature's howl. Once a creature becomes cursed in this way, she takes no additional penalty for being exposed to additional howlers' howls until the current howler curse is lifted. This is a sonic mind-affecting effect. The save DC is Charisma-based. Howler Howl: Curse-howl; save Will DC 12 negates; frequency 1/hour; effect 1 Wis damage; cure 1 save."},{"type":"Pain","kind":"Ex","details":"Whenever a creature takes damage from a howler's quill attack or its quill defense, that creature must make a successful DC 14 Reflex save or one quill breaks off in its flesh, causing the target to become sickened until all embedded quills are removed. Removing one quill requires a DC 15 Heal check made as a full-round action. For every 5 by which the check is exceeded, one additional quill can be removed. On a failed check, a quill is still removed, but the process deals 1d4+1 points of damage to the victim. The save DC is Dexterity-based."},{"type":"Quill Defense","kind":"Ex","details":"Any creature that strikes a howler with a non-reach melee weapon, unarmed strike, or natural weapon takes 1d4+1 points of piercing damage from the howler's quills and suffers from the howler's pain attack."}],"description":"The howler is a native to the Abyss, an Outer Plane where madness is the norm and cruelty is expected and often rewarded. The howler prowls these Abyssal realms, serving the role of a hungry predator like a lion or tiger, save for the fact that the typical howler is much more intelligent than a big cat. Worse, howlers have little interest in eating their prey-they need not feed to live, but rather enjoy the process of stalking, mauling, and killing living creatures. In a way, the act of inflicting intense pain and madness upon mortal life is what fills a howler's life instead of the desire to feed.\n\nThe howler's mane of razor-sharp quills makes it a poor choice of mount for most creatures, but it serves quite well as a guardian or sentinel-especially for outsiders, who may not enjoy the creature's constant howling, but aren't adversely affected by the supernatural sounds. When a howler sees prey, the tenor of its howls changes- howlers cannot speak, but they can use their howls to communicate quite a bit of information if required. They understand the Abyssal tongue, and when serving demons as guardians, their howls can not only alert their masters to the presence of intruders, but also to their number, appearance, and weaknesses.\n\nA howler is about the size of a tiger-12 ft. from snout to tail and weighing 6,000 pounds. They are normally pale in color, with darker quills and milky eyes.","ecology":"","habitat_society":""},{"name":"Hungry Flesh","cr":3,"xp":800,"alignment":"N","size":"Large","type":"ooze","init":-3,"senses":[{"type":"blindsight","modifier":"60 ft."},{"type":"scent"}],"ac":8,"ac_touch":6,"ac_flat_footed":8,"ac_mods":"-3 Dex, +2 natural, -1 size","hp":47,"hd":"5d8+25","hdvalue":5,"hp_mods":["regeneration 5 (acid or fire)"],"fort":6,"ref":-2,"will":-4,"defensive_abilities":["amorphous"],"immunities":["ooze traits"],"speed":[{"type":"land","speed":20},{"type":"swim","speed":20}],"melee":"slam +5 (1d6+4 plus disease and grab)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"constrict","details":"1d6+4 plus disease"}],"strength":16,"dexterity":5,"constitution":20,"wisdom":1,"charisma":1,"baseatk":3,"cmb":7,"cmb_special":"+4 vs. grapple","cmd":14,"cmd_special":"can't be tripped","sq":[{"type":"compression"},{"type":"monstrous growth"},{"type":"reactive regeneration"},{"type":"slime trail"}],"environments":["any land","any underground"],"organizations":["solitary","cluster (2-5)"],"treasure":"incidental","description_visual":"A quivering pile of tumorous flesh, this creature leaves a trail of slime as it hungrily searches for sustenance.","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Disease","kind":"Ex","details":"Tumor Infestation: Injury; save Fort DC 17; onset 1 minute; frequency 1/day; effect 1d2 Con and 1d2 Cha; cure 2 consecutive saves. Anyone who dies from tumor infestation turns into a hungry flesh 1d4 hours later. The save DC is Constitution-based."},{"type":"Monstrous Growth","kind":"Ex","details":"A hungry flesh gains growth points from its reactive regeneration ability or from eating creatures. When it consumes a creature that's been dead no more than an hour, it gains 1 growth point if that creature is of its size or one size category smaller, or 2 growth points if its meal is larger than it is. Eating a creature takes a full-round action if it is the same size or smaller than the hungry flesh or 1 minute if it is larger. Each time a hungry flesh reaches 5 growth points, it gains the giant creature simple template. This template stacks with itself each time the hungry flesh gains another 5 growth points, but the hungry flesh can't increase its size beyond Gargantuan. When it stops gaining growth points, a hungry flesh loses a single application of the giant creature simple template for each hour that passes."},{"type":"Reactive Regeneration","kind":"Ex","details":"Whenever a hungry flesh takes piercing or slashing damage, it regenerates 5 hit points and gains 1 growth point."},{"type":"Slime Trail","kind":"Ex","details":"A hungry flesh leaves behind a trail of slime that acts as a grease spell (DC 17). Any living creature that touches this slime with bare flesh must succeed at a Fortitude save (with a +4 bonus) or contract tumor infestation. The slime dries up after 1 minute. The save DC is Constitution-based."}],"description":"Created in a laboratory by an alchemist researching methods of regenerating human flesh, a hungry flesh is a freakish creature made of aggressive, malignant tissue. It lives only to feed and grow, and must consume large amounts of plant and animal matter to sustain itself. Each day, a hungry flesh must consume its own weight in food. A hungry flesh resists attempts to cut or pierce it, quickly repairing the damage and creating new fleshy growths. With the right food and attacks to catalyze its growth, a hungry flesh can balloon to twice its normal size in minutes. A hungry flesh can grow to Gargantuan size. A hungry flesh starts out at approximately 7 ft. in diameter, and weighs 3,000 pounds.","ecology":"","habitat_society":""},{"name":"Immured","cr":3,"xp":800,"alignment":"NE","size":"Medium","type":"undead","init":4,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["breathlessness (10 ft., DC 14)"],"ac":16,"ac_touch":10,"ac_flat_footed":16,"ac_mods":"+6 natural","hp":26,"hd":"4d8+8","hdvalue":4,"fort":3,"ref":1,"will":5,"immunities":["undead traits"],"weaknesses":["bound"],"speed":[{"type":"land","speed":30}],"melee":"slam +6 (1d4+4)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"breach"},{"type":"seize"}],"strength":16,"dexterity":11,"intelligence":5,"wisdom":13,"charisma":14,"baseatk":3,"cmb":6,"cmb_special":"+2 vs. drag","cmd":16,"cmd_special":"+2 vs. drag","feats":[{"feat":"Improved Drag","type":"bonus"},{"feat":"Improved Initiative"},{"feat":"Power Attack"}],"skills":[{"skill":"Perception","value":6},{"skill":"Stealth","value":5}],"languages":["Common (can't speak)"],"environments":["any urban"],"organizations":["solitary","gang (2-5)"],"treasure":"standard","description_visual":"Through cracked, sickly blue lips, this pallid humanoid figure emits deep gasps as if struggling to breathe.","source":"Daughters Of Fury","special_abilities":[{"type":"Aura of Breathlessness","kind":"Su","details":"The agonized gasping of an immured displaces oxygen within 10 ft. of it, automatically extinguishing nonmagical fires within this range. Breathing creatures within the aura must hold their breath or risk suffocation. Whenever an immured deals nonlethal damage to a creature holding its breath in the aura, the duration the target can hold its breath for decreases by a number of rounds equal to the nonlethal damage dealt. The immured cannot dismiss this aura."},{"type":"Bound","kind":"Su","details":"Immured are bound to the locations in which they died. Each hour an immured remains away from the tomb or building in which it died, it takes 1d6 points of damage that can't be healed until it returns to its place of death."},{"type":"Breach","kind":"Su","details":"As a swift action, an immured can touch a nonmagical wall and open a spatial rift. The touched 5-foot section of wall (which can be up to 2 ft. thick) effectively ceases to exist for 2 rounds, except for a dark, semisolid membrane that blocks line of sight through the rift. The immured can see, move, attack, or even drag a target through the rift without penalty. Other creatures can move through the rift, treating it as difficult terrain. After 2 rounds, the rift closes, pushing anything inside it into the nearest open space."},{"type":"Seize","kind":"Ex","details":"An immured can choose to deal nonlethal damage with its slam attack with no penalty on the attack roll. In addition, an immured that deals nonlethal damage with its slam attack can attempt a drag combat maneuver against the target as a free action."}],"description":"Immured are undead remains of those who died of slow suffocation in a confined, lightless space. Their feelings of abject terror and desperate desire to escape before death manifest as an ability to open temporary rifts in reality. Although they loathe the bright lights and open spaces of the world outside, they occasionally emerge to violently hush any sounds that disturb their repose. Some immured find the last gasps of dying creatures intoxicating, so they seek out victims to choke night after night.\n\nWhile an accidental live burial can trigger the birth of an immured, most of these unfortunates are brought about by purposeful malevolence, such as being walled in as a form of torture or execution in life. In cultures obsessed with undeath or the afterlife, living servants are sometimes honored by being entombed with their masters, which can create immured.\n\nAn immured is 6 ft. tall and weighs 100 pounds.","ecology":"","habitat_society":""},{"name":"Juvenile Rukh","cr":3,"xp":800,"alignment":"N","size":"Large","type":"magical beast","init":2,"senses":[{"type":"low-light vision"}],"ac":15,"ac_touch":11,"ac_flat_footed":13,"ac_mods":"+2 Dex, +4 natural, -1 size","hp":37,"hd":"5d10+10","hdvalue":5,"fort":6,"ref":6,"will":2,"speed":[{"type":"land","speed":20},{"type":"fly","speed":40,"maneuverability":"poor"}],"melee":"2 bites +7 (1d8+2), 2 talons +6 (1d6+2)","space":"10 ft.","reach":"5 ft.","strength":14,"dexterity":15,"constitution":14,"intelligence":2,"wisdom":13,"charisma":11,"baseatk":5,"cmb":8,"cmd":20,"feats":[{"feat":"Flyby Attack"},{"feat":"Snatch"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Fly","value":-4},{"skill":"Perception","value":17}],"environments":["warm deserts","warm mountains"],"organizations":["pair","flock (3d4)"],"treasure":"incidental","description_visual":"This gigantic two-headed vulture has greasy, night-black wings and sharp talons.","group":"Rukh","source":"PFRPG Bestiary 4","description":"Rukhs are foul-tempered creatures related to rocs, except they resemble two-headed vultures instead of raptors. They hunt live prey and carrion, typically gliding high above the desert in search of things to eat. They avoid creatures of their size or larger, preferring easier prey-horses, camels, and humanoids for adult rukhs, or Medium and Small creatures for juveniles. They nest on mountains and in cliffside caves, as they are too large to roost in trees. Few young rukhs reach adulthood, as many tribes and caravans hunt them for meat, often using a lone, weak-looking scout to lure a hungry juvenile into striking distance for an ambush. A typical adult rukh stands nearly 35 ft. tall and has a wingspan of more than 60 ft. Most are scrawny due to hunger. Coupled with their lightweight bones for easier flying, they rarely top 800 pounds. Juvenile rukhs usually stand about 10 ft. tall, with a relatively small wingspan of nearly 18 ft., and weigh about 200 pounds.","ecology":"","habitat_society":""},{"name":"Kech","cr":3,"xp":800,"alignment":"NE","size":"Medium","type":"monstrous humanoid","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":16,"ac_touch":13,"ac_flat_footed":13,"ac_mods":"+2 Dex, +1 dodge, +3 natural","hp":26,"hd":"4d10+4","hdvalue":4,"fort":2,"ref":6,"will":5,"speed":[{"type":"land","speed":40},{"type":"climb","speed":20}],"melee":"bite +5 (1d6+1), 2 claws +5 (1d4+1)","ranged":"longbow +6 (1d8/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"rend","details":"2 claws 1d4 +1"}],"spell_like_abilities_caster_level":4,"spell_like_abilities_concentration":5,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"pass without trace"}]}],"strength":13,"dexterity":15,"constitution":12,"intelligence":10,"wisdom":12,"charisma":11,"baseatk":4,"cmb":5,"cmd":18,"feats":[{"feat":"Dodge"},{"feat":"Mobility"}],"skills":[{"skill":"Acrobatics","value":6,"special":"+10 when jumping"},{"skill":"Climb","value":16},{"skill":"Perception","value":10},{"skill":"Stealth","value":13,"special":"+19 in forests and jungles"}],"languages":["Kech"],"environments":["warm forests"],"organizations":["solitary","pair","tribe (3-36 plus 2-6 dire apes)"],"treasure":"standard (longbow with 20 arrows)","description_visual":"This hairless simian's leathery skin has a camouf lage pattern to it that shifts and changes as the creature moves.","source":"PFRPG Bestiary 3","description":"Not quite man nor ape, the kech is a hairless primate that dwells in the deepest jungles. There they live in sizable tribes, relying upon their uncanny coloration and skill with bows to hunt prey. The green-and-brown camouf lage coloration of a kech's flesh shifts and adapts to all surroundings to aid in stealth, but works particularly well in forests or jungles. This, combined with its uncanny ability to move through any terrain and leave no trace of its passage, makes the kech a masterful ambush hunter. A kech is 6 ft. tall and weighs 240 pounds.\n\nThese creatures prefer to dwell in ruined jungle buildings, and when presented with an opportunity to seize a remote town, slaughter the citizens, and move in, the typical kech tribe doesn't hesitate. Keches are as cruel as they are stealthy, and most jungle villages don't realize\n\nthat they are under attack by a band of keches until the battle is already decided, with more than half the village dead in their beds, never having had the chance to awake and sound an alarm. Once a village does rouse to mount a resistance, the keches often seek to subdue remaining victims rather than kill them. Those who are slaughtered are inevitably eaten within 24 hours as part of a tremendous victory feast. Prisoners are often kept in cages in close proximity to the feasting, for keches enjoy the sound of wailing as their victims watch their kin being consumed.\n\nA kech tribe is typically led by a chieftain with 2-4 levels of ranger or fighter. Keches value magical support, particularly divine magic, for the jungle has no shortage of methods to wound, poison, or sicken those who dwell within. A kech cleric is as likely to worship an evil deity as it is one of the Four Horsemen or an evil elemental lord, but most kech priests are in fact druids. The combination of restorative magic and power over the natural world is often too seductive a path for a devout kech to ignore. Kech druids typically take apes as animal companions, and even tribes that lack druids generally have a few well-trained guard apes among them.\n\nCannibalism is seen as a particularly vile taboo by keches-this prohibition extends to the consumption of ape or monkey flesh, but notably doesn't extend to the flesh of humanoids.","ecology":"","habitat_society":""},{"name":"Khaei","cr":3,"xp":800,"alignment":"N","size":"Small","type":"monstrous humanoid","init":5,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":15,"ac_touch":12,"ac_flat_footed":14,"ac_mods":"+1 Dex, +3 natural, +1 size","hp":30,"hd":"4d10+8","hdvalue":4,"fort":3,"ref":5,"will":4,"speed":[{"type":"land","speed":20}],"melee":"club +5 (1d4) or   touch +5 (lost time)","ranged":"sling +6 (1d3)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":4,"spell_like_abilities_concentration":6,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"blur"}]},{"frequency":"at-will","spells":[{"spell":"dancing lights"}]}],"strength":10,"dexterity":13,"constitution":14,"intelligence":7,"wisdom":10,"charisma":13,"baseatk":4,"cmb":3,"cmd":14,"feats":[{"feat":"Combat Reflexes"},{"feat":"Improved Initiative"}],"skills":[{"skill":"Perception","value":7},{"skill":"Stealth","value":16}],"languages":["Undercommon"],"environments":["any underground (beneath Kaer Maga)"],"organizations":["solitary","pair","gang (3-5)","village (6-30)"],"treasure":"standard","description_visual":"This short, stunted humanoid is bald and has weirdly twisted limbs, its body seeming to fade and come apart at the edges.","source":"Inner Sea Bestiary","special_abilities":[{"type":"Lost Time","kind":"Su","details":"As a touch attack, a khaei can touch a creature and prematurely age it. The creature touched must succeed at a DC 14 Fortitude save or take 1d4 points of Constitution damage and be permanently aged 1d10 years. This effect also deals 1d4 points of damage to the khaei. Effects from multiple khaei stack, though a single khaei can use this power on a given opponent only once."}],"description":"The khaei are a mystery even to themselves. Their twisted limbs give them an awkward, shambling gait, and their personalities are dull and incurious, making them seem in many ways to be simply degenerate humans. At the same time, their bodies' tendency to trail off into mist and shadow, combined with their weird magical attack, suggests they could be much more. A typical khaei stands 4 ft. tall and weighs 100 pounds.\n\nBy far the most unusual aspect of the khaei is their ability to manipulate time. A khaei in fear for her life can grab an attacker and forcefully age him by several years, creating enormous strain on the foe's body. This exertion does damage to the khaei as well, and thus is rarely used, but a would-be tyrant who considers the khaei easy pickings may find himself surrounded by a weeping mob that quickly ages him into decrepitude-then forgives and cares for him. The few scholars who know of the khaei's existence speculate that the creatures may themselves be somehow unstuck in time, perhaps sent back or forward from another era in preparation for a great event.\n\nKhaei live in small, isolated communities underground, often inhabiting a single cavern and refusing to explore beyond it or otherwise improve their situation. The only known enclave of khaei in the Inner Sea region is in the Dark Forest, a cavern deep beneath the city of Kaer Maga, where they serve as both subjects and prey for the mysterious dullahan called the Dark Rider. One of the most cherished stories of these khaei concerns a time and place-somewhere in either the past or the future- when there were many more of them, their cavern-forests linked by magical standing stones.","ecology":"","habitat_society":""},{"name":"Kirrix","cr":3,"xp":800,"alignment":"N","size":"Large","type":"magical beast","init":6,"senses":[{"type":"blindsense","modifier":"10 ft."},{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":14,"ac_touch":11,"ac_flat_footed":12,"ac_mods":"+2 Dex, +3 natural, -1 size","hp":34,"hd":"4d10+12","hdvalue":4,"fort":7,"ref":6,"will":2,"immunities":["disease"],"speed":[{"type":"land","speed":30},{"type":"burrow","speed":10},{"type":"climb","speed":20}],"melee":"bite +7 (1d8+6)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"expel pathogens"}],"strength":18,"dexterity":15,"constitution":17,"intelligence":5,"wisdom":12,"charisma":8,"baseatk":4,"cmb":9,"cmd":21,"cmd_special":"+8 vs. trip","feats":[{"feat":"Improved Initiative"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Climb","value":12},{"skill":"Perception","value":9},{"skill":"Stealth","value":3}],"languages":["Common (can't speak)"],"sq":[{"type":"compression"},{"type":"harbor pathogens"}],"environments":["any underground"],"organizations":["solitary","pair","pack (3-6)"],"treasure":"none","description_visual":"This sleek, weasel-like rodent has exaggerated whiskers and six short but stout legs.","source":"Monster Codex","special_abilities":[{"type":"Expel Pathogens","kind":"Ex","details":"When a kirrix hits with its bite attack, it can infect its target using its harbor pathogens ability (if any) with one disease it has stored, even if that disease can't normally be contracted via an injury. It can do this a number of times per day equal to its Constitution modifier. Alternatively, a kirrix can expend two uses of this ability to spray a disease in a 15-foot cone, exposing all creatures in the cone to the disease even if it can't normally be contracted by contact. Doing so depletes the kirrix's reserve of that disease."},{"type":"Harbor Pathogens","kind":"Ex","details":"A kirrix's body has innate features that let it clean up and contain diseases within ratfolk warrens. A kirrix collects diseases by consuming them off of objects or from the air (typically contact, ingested, or inhaled diseases), by ministering to a diseased creature (typically ingested or injury diseases), or by fighting a creature that imparts diseases and being subjected to one. The kirrix can store up to two types of diseases at a time in an organ near its throat. (A typical kirrix has filth fever and bubonic plague stored.) A kirrix can harmlessly digest an unwanted disease as a full-round action. If the creature consumes a mold or another substance that causes disease, it clears the surface of disease. If it ingests a diseased creature's blood (either by licking an open wound or biting the creature), it can produce an antiplague secretion, which it can use on itself or apply to others. Treat this as though the kirrix were using the Heal skill to treat disease with a +12 bonus."}],"description":"Ratfolk have just as much enthusiasm for alchemy as they do for rodents, and they combined these two interests to create the kirrix-the result of generations of riding rat husbandry combined with regular infusions. These alchemical modifications have given kirrixes six legs and the ability to consume and transmit diseases without ill effect to the creatures themselves.\n\nMany ratfolk settlements raise these gregarious creatures, with whom the ratfolk share their warrens in a symbiotic relationship. The kirrixes prowl the ratfolk tunnels and act as scavengers-searching for unfamiliar scents, consuming detritus, and removing harmful diseases from the ratfolk settlement. If the warren comes under attack, the kirrixes act as guards, and squeeze through or block tunnels as necessary to buy time for their ratfolk allies to escape.\n\nA typical adult kirrix is 9 ft. long and usually weighs under 500 pounds.","ecology":"","habitat_society":""},{"name":"Kyrana","cr":3,"xp":800,"alignment":"NE","size":"Medium","type":"dragon","subtypes":["fire"],"init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":14,"ac_touch":12,"ac_flat_footed":12,"ac_mods":"+2 Dex, +2 natural","hp":30,"hd":"4d12+4","hdvalue":4,"hp_mods":["fiery regeneration"],"fort":5,"ref":6,"will":3,"immunities":["dragon traits","fire","paralysis","sleep"],"weaknesses":["vulnerable to cold"],"speed":[{"type":"land","speed":30}],"melee":"bite +8 (1d4+3), 2 claws +7 (1d3+3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"breath weapon","details":"20-ft. line, 3d6 fire damage, Reflex DC 13 half, usable every 1d4 rounds"}],"strength":16,"dexterity":15,"constitution":12,"intelligence":3,"wisdom":9,"charisma":6,"baseatk":4,"cmb":7,"cmd":19,"cmd_special":"+4 vs. trip","feats":[{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Climb","value":10},{"skill":"Perception","value":9}],"languages":["Draconic"],"environments":["any underground","any warm deserts"],"organizations":["solitary","pair"],"treasure":"standard","description_visual":"Long spines jut from the head and neck of this red-scaled iguana, and fire trickles from its open mouth.","source":"Monster Codex","special_abilities":[{"type":"Fiery Regeneration","kind":"Su","details":"A kyrana doesn't take damage from fire-based attacks. Additionally, when a kyrana would normally take fire damage, it heals that number of hit points, to a maximum of 5 hit points per round. A kyrana can't use its breath weapon to heal itself."}],"description":"Kyranas are large, iguana-like relatives of true dragons, with low intelligence and an affinity for fire. Though quite weak as dragons go, kyranas are still dangerous enough to command the fear and respect of kobolds, who often encounter the fire-breathing dragons while digging deep tunnels.\n\nKyranas are primarily subterranean creatures, though they can occasionally be found on the surface in extremely hot or volcanic areas. Healed supernaturally by contact with fire, they often spend their time swimming in volcanic calderas or underground lava lakes, taking in geothermic energy and storing it in order to release it on their prey as lines of fiery breath.\n\nIf kyranas stayed confined to their magma homes, they would present little problem to other races. Unfortunately, they're extremely territorial, even toward their own offspring. Kyranas are born in clutches of six to 12 eggs, and raised by both parents. As soon as the creatures reach adulthood at the age of 18 months, however, the parents turn on their offspring and drive them from the nest. The exiled kyranas then split up and wander the surrounding tunnels, traveling hundreds of miles in search of any source of heat. That means they often come waddling into inhabited areas, snorting and ready to burn anyone standing between them and the hearth. Adventurers may find their campfires claimed by a greedy kyrana, or end up being followed for their torchlight. Kobolds often use these barely intelligent dragons as heavy artillery, employing fire arrows and flaming traps to lure them into conf lict with enemies.\n\nAn adult kyrana is 5 ft. long and weighs 300 pounds on average.","ecology":"","habitat_society":""}];
